import json

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # First six numbers are the triangle vertices (x1 y1 x2 y2 x3 y3)
    try:
        x1, y1, x2, y2, x3, y3 = map(float, data[:6])
    except ValueError:
        # If the coordinates are not valid numbers, exit silently
        return

    triangle = [[x1, y1], [x2, y2], [x3, y3]]

    # The next number is n, the count of points
    if len(data) < 7:
        n = 0
        points = []
    else:
        try:
            n = int(float(data[6]))
        except ValueError:
            n = 0
        # Remaining numbers are point coordinates
        point_coords = data[7:]
        points = []
        # Take pairs up to n points (ignore any excess)
        for i in range(min(n, len(point_coords) // 2)):
            xi = float(point_coords[2 * i])
            yi = float(point_coords[2 * i + 1])
            points.append([xi, yi])

    output = {
        "triangle": triangle,
        "n": n,
        "points": points
    }

    json.dump(output, sys.stdout)

if __name__ == "__main__":
