    expected_len = 1 + 2 * n
    if len(data) < expected_len:
        # Not enough data; just use what we have
        coord_tokens = data[1:]
    else:
        coord_tokens = data[1:expected_len]

    # Parse coordinate pairs
    it = iter(coord_tokens)
    for x_str, y_str in zip(it, it):
        try:
            x = int(x_str)
            y = int(y_str)
        except ValueError:
            # If conversion fails, skip this pair
            continue
        points.append([x, y])

    output = {
        "n": n,
        "points": points
    }

    print(json.dumps(output))

if __name__ == "__main__":
    main()

