import sys
import json

def main() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    # first line: n capacity
    first = data[0].strip().split()
    if len(first) != 2:
        raise ValueError("First line must contain exactly two integers: n and capacity")
    n, capacity = map(int, first)

    # second line: n item sizes (could be split across multiple lines, so join all remaining lines)
    sizes_str = " ".join(line.strip() for line in data[1:])
    sizes = list(map(int, sizes_str.split()))
    if len(sizes) != n:
        raise ValueError(f"Expected {n} item sizes, but got {len(sizes)}")

    output = {
        "n": n,
        "capacity": capacity,
        "items": sizes
    }

    json.dump(output, sys.stdout)

if __name__ == "__main__":
    main()
